/* @autogenerated */
package net.civeira.phylax.bootstrap.install;

import java.io.IOException;
import java.io.InputStream;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.transaction.Transactional;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.infrastructure.migration.MigrationSeed;
import net.civeira.phylax.feature.template.template.domain.Template;
import net.civeira.phylax.feature.template.template.domain.TemplateChangeSet;
import net.civeira.phylax.feature.template.template.domain.TemplateChannelOptions;
import net.civeira.phylax.feature.template.template.domain.gateway.TemplateCommandRepositoryGateway;
import net.civeira.phylax.feature.template.template.domain.gateway.TemplateFilter;
import net.civeira.phylax.feature.template.templateversion.domain.TemplateVersion;
import net.civeira.phylax.feature.template.templateversion.domain.TemplateVersionChangeSet;
import net.civeira.phylax.feature.template.templateversion.domain.gateway.TemplateVersionCommandRepositoryGateway;

/**
 * Seeds the email templates of the alerts (trait observable-notification): observe.alert.firing and
 * observe.alert.resolved, channel MAIL, theme corporate-mail, with an HTML and a text body in
 * English (default version) and Spanish ({@code es}). The bodies are files of the trait,
 * {@code migration/seed/templates/observe/}. Idempotent: a template that exists is never touched,
 * so the versions that the operator edits survive.
 */
@ApplicationScoped
@RequiredArgsConstructor
public class InstallObserveNotification implements MigrationSeed {

  private static final String BASE = "migration/seed/templates/observe/";
  private static final String THEME = "corporate-mail";

  private final TemplateCommandRepositoryGateway templates;
  private final TemplateVersionCommandRepositoryGateway templateVersions;

  @Override
  public String id() {
    return "seed/install-observe-notification";
  }

  @Override
  public int order() {
    // After InstallNotification (20), InitialDocument (30, the corporate-mail theme) and
    // InstallObserveDocuments (35)
    return 36;
  }

  @Override
  @Transactional
  public void run() {
    createTemplate("observe.alert.firing", "alert-firing",
        "[{{app.title}}] {{rule.name}}: {{alert.summary}}",
        "[{{app.title}}] {{rule.name}}: {{alert.summary}}");
    createTemplate("observe.alert.resolved", "alert-resolved",
        "[{{app.title}}] Resolved: {{rule.name}}", "[{{app.title}}] Resuelta: {{rule.name}}");
  }

  private void createTemplate(final String code, final String file, final String subject,
      final String subjectEs) {
    if (templates.find(TemplateFilter.builder().code(code).build()).isPresent()) {
      return;
    }
    Template created = templates.create(Template.create(new TemplateChangeSet().newUid().code(code)
        .channel(TemplateChannelOptions.MAIL).theme(THEME).enabled(true)));
    templateVersions
        .create(TemplateVersion.create(new TemplateVersionChangeSet().newUid().template(created)
            .subject(subject).contentHtml(read(file + ".html")).contentText(read(file + ".txt"))));
    templateVersions.create(TemplateVersion.create(
        new TemplateVersionChangeSet().newUid().template(created).locale("es").subject(subjectEs)
            .contentHtml(read(file + ".es.html")).contentText(read(file + ".es.txt"))));
  }

  static String read(final String name) {
    try (InputStream in =
        Thread.currentThread().getContextClassLoader().getResourceAsStream(BASE + name)) {
      if (null == in) {
        throw new IllegalStateException("Missing seed template " + BASE + name);
      }
      return new String(in.readAllBytes(), StandardCharsets.UTF_8);
    } catch (IOException ex) {
      throw new UncheckedIOException(ex);
    }
  }
}
